const Navigation = ({ onNavigate }: Props) => {
  const { pathname } = useLocation()
  return (
    <ul className="flex flex-col md:flex-row gap-2 md:gap-4">
      {navItems.map(({ to, label }) => (
        <li key={to}>
          <Link
            to={to}
            onClick={onNavigate}
            className={`text-sm font-medium transition-colors hover:text-primary ${
              pathname === to ? 'text-primary' : 'text-gray-500 dark:text-gray-400'
            }`}
          >
            {label}
          </Link>
        </li>
      ))}
    </ul>
  )
}

const columns = [
  columnHelper.accessor('name', {
    header: 'Tool',
    cell: ({ row }) => (
      <div className="flex items-center gap-3">
        <ToolIcon url={row.original.icon_url || ''} category={row.original.owner_department} />
        <span>{row.original.name}</span>
      </div>
    ),
  }),
  columnHelper.accessor('owner_department', { header: 'Department' }),
  columnHelper.accessor('active_users_count', { header: 'Users' }),
  columnHelper.accessor('monthly_cost', {
    header: 'Monthly Cost',
    cell: ({ getValue }) =>
      new Intl.NumberFormat('en-US', {
        style: 'currency',
        currency: 'EUR',
        maximumFractionDigits: 0,
      }).format(getValue()),
  }),
]

type Props = {
  cardname: string | 'Card Name'
  tailwindBgColor?: string | 'bg-gray-300'
  cardlogo: React.ReactNode
  value: string | number | React.ReactNode | 'Value'
  performance?: string | '+0'
}

const KPICard = (props: Props) => {
  return (
    <div className="p-6 rounded-xl bg-white text-gray-700 shadow-sm dark:bg-tertiary-dark dark:text-white dark:shadow-gray-700">
      <div className="flex items-center justify-between gap-6 mb-16">
        {props.cardname}
        <div
          className={`${props.tailwindBgColor ? props.tailwindBgColor : 'bg-gray-300'} text-white w-10 h-10 rounded-lg flex items-center justify-center`}
        >
          {props.cardlogo}
        </div>
      </div>
      <h2 className="text-xl font-bold">{props.value}</h2>
      <p
        className={`mt-2 px-3 rounded-xl w-max text-white ${props.tailwindBgColor ? props.tailwindBgColor : 'bg-gray-300'}`}
      >
        {props.performance}
      </p>
    </div>
  )
}

